public final class ContextDependentRoundRunner {
    private static int checks;
    private interface Attempt{void run()throws Exception;}
    private static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    private static void reject(Attempt a,String why)throws Exception{boolean no=false;try{a.run();}catch(Exception expected){no=true;}require(no,why);}
    private static Policy policy(){return new Policy(2000000,1000,100,64000000,200000);}
    private static Mind memory()throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);return m;}
    private static Rule raw(Mind m,String text)throws Exception{return (Rule)m.compileLine(text,false,new LinkedList<ITerm>());}
    private static Member member(Mind m,int id,boolean local)throws Exception{return new Member(m,ContextProductionInventory.inspect(m,new UUID(0,id),3,local,Collections.emptyList(),1000));}
    private static Ref ref(Member m,Rule r){return new Ref(m.inventory.context,r.getId());}
    private static Step horn(Member m,Rule r,Donor... ds){return new Step(ref(m,r),-1,Arrays.asList(ds));}
    private static Step residual(Member m,Rule r,String kept,Map<String,Donor> ds)throws Exception{List<Donor> donors=new ArrayList<>();int at=-1,index=0;for(Domain d:r.getTree().get(0)){String p=d.getPredicate(m.actual).getName(m.actual);if(p.equals(kept))at=index;else donors.add(ds.get(p));index++;}return new Step(ref(m,r),at,donors);}
    private static Map<String,List<Step>> empty(Member x,List<Cut> cuts){Map<String,List<Step>> map=new LinkedHashMap<>();map.put(ContextDependentCutInspection.local(x.inventory.context),Collections.emptyList());for(Cut cut:cuts)map.put(cut.key,Collections.emptyList());return map;}
    private static Request request(Round... rounds){return new Request(policy(),10000,Arrays.asList(rounds));}
    private static Result inspect(Member x,List<Cut> cuts,Round... rounds)throws Exception{return ContextDependentRoundInspection.inspect(x,cuts,request(rounds));}
    private static void originalAndPrivate()throws Exception{
        Mind xm=memory(),am=memory(),bm=memory();Rule h=raw(xm,"!@x left(x)&&right(x)->p(x);"),left=raw(am,"!left(1);"),p=raw(am,"!p(1);"),right=raw(bm,"!right(1);"),no=raw(bm,"!~p(1);");Member x=member(xm,1,true),a=member(am,2,false),b=member(bm,3,false);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b));
        Map<String,Donor> donors=new HashMap<>();donors.put("right",Donor.original(ref(b,right)));donors.put("p",Donor.original(ref(b,no)));Step produce=residual(x,h,"left",donors);
        for(boolean reverse:new boolean[]{false,true}){
            List<Cut> cuts=reverse?Arrays.asList(cb,ca):Arrays.asList(ca,cb);Map<String,List<Step>> first=empty(x,cuts);first.put(cb.key,Collections.singletonList(produce));Result result=inspect(x,cuts,new Round(first),new Round(empty(x,cuts)));Barrier r0=result.barriers.get(0),r1=result.barriers.get(1);
            require(r0.cuts.get(ca.key).products.isEmpty()&&r0.cuts.get(ca.key).finalUnitRefutations.isEmpty(),"A cannot see same-round B product");require(r0.common.equals(Collections.singleton(new Ticket(0,cb.key,0))),"X-dependent signed consequence exported only at full barrier");
            ContextDependentProductionInspection.Row row=r1.cuts.get(ca.key).products.get(0);require(!row.positive&&row.predicate.equals("left")&&row.sources.size()==3,"A receives exact negative proof, not sibling premises");require(r1.cuts.get(ca.key).originalUnitRefutations.isEmpty()&&!r1.cuts.get(ca.key).finalUnitRefutations.isEmpty(),"second synchronous round qualifies negative B product in A");require(r1.cuts.get(ca.key).finalUnitRefutations.stream().anyMatch(c->c.sources.size()==4&&c.sources.stream().anyMatch(s->s.context.equals(a.inventory.context)&&s.rule==left.getId())),"collision includes A left and all three producing Sources");require(r1.cuts.get(ContextDependentCutInspection.local(x.inventory.context)).finalUnitRefutations.isEmpty(),"common negative consequence alone is not a local X contradiction");
            reject(()->r1.common.clear(),"barrier immutable");reject(()->r1.cuts.clear(),"cut results immutable");
        }
        Map<String,List<Step>> sibling=empty(x,Arrays.asList(ca,cb));sibling.put(ca.key,Collections.singletonList(new Step(ref(x,h),produce.retainedLiteral,produce.donors)));reject(()->inspect(x,Arrays.asList(ca,cb),new Round(sibling)),"sibling original donors cannot be borrowed directly");
        Mind px=memory(),pa=memory(),pb=memory();raw(px,"!anchor(1);");Rule seed=raw(pa,"!seed(1);"),hp=raw(pa,"!@x seed(x)->p(x);"),hn=raw(pa,"!@x p(x)->next(x);");raw(pb,"!~p(1);");Rule outside=raw(pb,"!@x p(x)->outside(x);");Member mx=member(px,11,true),ma=member(pa,12,false),mb=member(pb,13,false);Cut ac=new Cut(null,Collections.singletonList(ma)),bc=new Cut(null,Collections.singletonList(mb));List<Cut> cuts=Arrays.asList(ac,bc);Map<String,List<Step>> first=empty(mx,cuts);first.put(ac.key,Collections.singletonList(horn(ma,hp,Donor.original(ref(ma,seed)))));Map<String,List<Step>> second=empty(mx,cuts);second.put(ac.key,Collections.singletonList(horn(ma,hn,Donor.carried(new Ticket(0,ac.key,0)))));Result privateResult=inspect(mx,cuts,new Round(first),new Round(second));require(privateResult.barriers.get(0).common.isEmpty()&&privateResult.barriers.get(1).common.isEmpty(),"foreign-only productions stay private in later rounds");require(privateResult.barriers.get(1).cuts.get(ac.key).products.size()==2,"own private frontier is retained and reusable");require(privateResult.barriers.get(1).cuts.get(bc.key).products.isEmpty()&&privateResult.barriers.get(1).cuts.get(bc.key).finalUnitRefutations.isEmpty(),"B does not qualify A's private p against its negative p");
        Map<String,List<Step>> illegal=empty(mx,cuts);illegal.put(bc.key,Collections.singletonList(horn(mb,outside,Donor.carried(new Ticket(0,ac.key,0)))));reject(()->inspect(mx,cuts,new Round(first),new Round(illegal)),"foreign private donor is unavailable even with valid B producer");
        Map<String,List<Step>> missing=empty(x,Arrays.asList(ca,cb));missing.remove(ca.key);reject(()->inspect(x,Arrays.asList(ca,cb),new Round(missing)),"incomplete barrier refuses whole result");reject(()->ContextDependentRoundInspection.inspect(x,Arrays.asList(ca,ca),request()),"split cut refused even without rounds");reject(()->ContextDependentRoundInspection.inspect(x,Arrays.asList(ca,cb),new Request(policy(),1,Arrays.asList(new Round(empty(x,Arrays.asList(ca,cb)))))),"capacity exhaustion exposes no earlier cut result");
    }
    private static void barriersAndOpposition()throws Exception{
        Mind xm=memory(),am=memory(),bm=memory();Rule hp=raw(xm,"!@x a(x)->p(x);"),hn=raw(xm,"!@x b(x)->~p(x);");Rule av=raw(am,"!a(1);"),bv=raw(bm,"!b(1);");Member x=member(xm,21,true),a=member(am,22,false),b=member(bm,23,false);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b));List<Cut> cuts=Arrays.asList(ca,cb);Map<String,List<Step>> first=empty(x,cuts);first.put(ca.key,Collections.singletonList(horn(x,hp,Donor.original(ref(a,av)))));Map<String,Donor> ds=new HashMap<>();ds.put("b",Donor.original(ref(b,bv)));first.put(cb.key,Collections.singletonList(residual(x,hn,"p",ds)));Result result=inspect(x,cuts,new Round(first),new Round(empty(x,cuts)));require(result.barriers.get(0).cuts.values().stream().allMatch(c->c.finalUnitRefutations.isEmpty()),"opposite sibling products do not leak inside producing round");require(result.barriers.get(1).cuts.values().stream().allMatch(c->!c.finalUnitRefutations.isEmpty()),"opposite common products collide at next receiving qualification, including local X");require(result.barriers.get(1).cuts.get(ContextDependentCutInspection.local(x.inventory.context)).finalUnitRefutations.stream().anyMatch(c->c.sources.size()==4),"direct common opposition retains both complete proofs");
        Map<String,List<Step>> same=empty(x,cuts);same.put(ca.key,Collections.singletonList(horn(x,hp,Donor.carried(new Ticket(0,cb.key,0)))));reject(()->inspect(x,cuts,new Round(same)),"same/future barrier ticket refused");
        Mind tx=memory(),ta=memory(),tb=memory();Rule th=raw(tx,"!@x a(x)&&b(x)->out(x);"),aa=raw(ta,"!a(1);"),bb=raw(tb,"!b(1);");Member xx=member(tx,31,true),xa=member(ta,32,false),xb=member(tb,33,false);Cut trust=new Cut("together",Arrays.asList(xb,xa));Map<String,List<Step>> tr=empty(xx,Collections.singletonList(trust));tr.put(trust.key,Collections.singletonList(horn(xx,th,Donor.original(ref(xa,aa)),Donor.original(ref(xb,bb)))));Result trusted=inspect(xx,Collections.singletonList(trust),new Round(tr));require(trusted.barriers.get(0).common.size()==1&&trusted.barriers.get(0).cuts.get(trust.key).products.get(0).sources.size()==3,"all physical TRUST members form one productive cut");
    }
    private static void alternatives()throws Exception{
        Mind xm=memory(),am=memory(),bm=memory(),cm=memory();Rule hp=raw(xm,"!@x seed(x)->p(x);"),hq=raw(xm,"!@x p(x)->q(x);"),back=raw(xm,"!@x q(x)->p(x);");Rule av=raw(am,"!seed(1);"),bv=raw(bm,"!seed(1);");raw(cm,"!~p(1);");Member x=member(xm,41,true),a=member(am,42,false),b=member(bm,43,false),c=member(cm,44,false);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b)),cc=new Cut(null,Collections.singletonList(c));List<Cut> cuts=Arrays.asList(cc,cb,ca);Map<String,List<Step>> first=empty(x,cuts);first.put(ca.key,Arrays.asList(horn(x,hp,Donor.original(ref(a,av))),horn(x,hq,Donor.earlier(0)),horn(x,back,Donor.earlier(1))));first.put(cb.key,Collections.singletonList(horn(x,hp,Donor.original(ref(b,bv)))));Result result=inspect(x,cuts,new Round(first),new Round(empty(x,cuts)));Barrier barrier=result.barriers.get(1);require(barrier.common.size()==4,"equal products and strict Source supersets are not deduplicated");ContextDependentProductionInspection.Result receiver=barrier.cuts.get(cc.key);require(receiver.products.size()==4,"receiving pool retains both physical alternatives plus derived superset");Set<Set<ContextProductionCapture.Source>> proofs=new HashSet<>();for(ContextDependentProductionInspection.Refutation collision:receiver.finalUnitRefutations)proofs.add(collision.sources);require(proofs.size()>=3,"all physical and strict-superset collision alternatives survive");require(proofs.stream().anyMatch(proof->proof.size()==5),"longer proof with strict additional whole Sources remains available");require(av.getId()==bv.getId(),"duplicate native IDs exercise qualified source keys");
        Map<String,List<Step>> tooLate=empty(x,cuts);tooLate.put(cb.key,Collections.singletonList(horn(x,hq,Donor.carried(new Ticket(0,ca.key,0)))));reject(()->inspect(x,cuts,new Round(tooLate)),"same-round cross-cut donor refused independent of lexical evaluation order");
        Map<String,List<Step>> later=empty(x,cuts);later.put(cb.key,Collections.singletonList(horn(x,hq,Donor.carried(new Ticket(3,ca.key,0)))));reject(()->inspect(x,cuts,new Round(first),new Round(later)),"future ticket cannot be guessed");
        Map<String,List<Step>> forward=empty(x,cuts);forward.put(ca.key,Collections.singletonList(horn(x,hq,Donor.earlier(0))));reject(()->inspect(x,cuts,new Round(forward)),"self/forward local product refused");
        Map<String,List<Step>> capped=new LinkedHashMap<>(first);capped.put(cb.key,Arrays.asList(horn(x,hp,Donor.original(ref(b,bv))),horn(x,hq,Donor.earlier(0))));String before=x.inventory.fingerprint;reject(()->ContextDependentRoundInspection.inspect(x,cuts,new Request(new Policy(2000000,1000,4,64000000,200000),10000,Arrays.asList(new Round(capped)))),"total ancestral history cap refuses entire barrier");require(before.equals(ContextProductionInventory.inspect(xm,x.inventory.context,3,true,Collections.emptyList(),1000).fingerprint),"history failure never writes originals");
    }
    private static void dependencies()throws Exception{
        for(int width:new int[]{1,7,17,65}){
            Mind xm=memory(),am=memory(),bm=memory();StringBuilder prefix=new StringBuilder(),args=new StringBuilder();for(int i=0;i<width;i++){prefix.append("@x").append(i).append(' ');if(i>0)args.append(',');args.append('x').append(i);}Rule h=raw(xm,"!"+prefix+"@u @b rel("+args+",u,b)->out("+args+",u,b);");Rule seed=raw(bm,"!"+prefix+"$u @b rel("+args+",u,b);");Rule join=raw(am,"!"+prefix+"@u out("+args+",u,1)&&out("+args+",u,2)->bad("+args+",u);");raw(am,"!"+prefix+"@u ~bad("+args+",u);");Member x=member(xm,100+width,true),a=member(am,200+width,false),b=member(bm,300+width,false);Cut ca=new Cut(null,Collections.singletonList(a)),cb=new Cut(null,Collections.singletonList(b));List<Cut> cuts=Arrays.asList(ca,cb);Map<String,List<Step>> first=empty(x,cuts);first.put(cb.key,Collections.singletonList(horn(x,h,Donor.original(ref(b,seed)))));Map<String,List<Step>> second=empty(x,cuts);second.put(ca.key,Collections.singletonList(horn(a,join,Donor.carried(new Ticket(0,cb.key,0)),Donor.carried(new Ticket(0,cb.key,0)))));Result result=inspect(x,cuts,new Round(first),new Round(second));List<ContextDependentProductionInspection.Row> rows=result.barriers.get(1).cuts.get(ca.key).products;ContextDependentProductionInspection.Row row=rows.get(1);ContextDependentProductionInspection.TermView witness=row.arguments.get(width);require(witness.kind==ContextDependentProductionInspection.Kind.APPLICATION&&witness.arguments.size()==width,"transport retains preceding universal dependency width");require(witness.symbolSource.context.equals(b.inventory.context)&&witness.symbolSource.rule==seed.getId(),"transport witness identity is physical B Source, not receiving copy");for(int i=0;i<width;i++)require(witness.arguments.get(i)==row.arguments.get(i),"common replay preserves coordinate sharing "+i);require(!result.barriers.get(1).cuts.get(ca.key).finalUnitRefutations.isEmpty(),"same dependent witness at b=1 and b=2 combines and refutes bad");require(result.barriers.get(1).common.size()==2,"foreign producer depending on common X proof exports at next barrier");
        }
    }
    private static final class Fixture implements AutoCloseable{
        final User user=new User();final DB db=new DB();final Mind root;
        Fixture(Path d,String name)throws Exception{user.setDatabaseDir(d+File.separator);user.setUserDir(Files.createDirectories(d.resolve("operator")).toString());db.init(user);Mind m=new Mind(user);user.setCurrentMind(m);root=(Mind)m.useStorage(name);user.setCurrentMind(root);}
        @Override public void close()throws Exception{if(user.getCurrentMind().isStorageUsed())user.setCurrentMind(user.getCurrentMind().closeStorage());}
    }
    private static void owning()throws Exception{
        Path dir=Files.createTempDirectory("dependent-round-db-");try(Fixture a=new Fixture(dir,"A")){require(a.root.compile("!left(1); !p(1);",null,false),"A fixture");}try(Fixture b=new Fixture(dir,"B")){require(b.root.compile("!right(1); !~p(1);",null,false),"B fixture");}
        for(boolean reverse:new boolean[]{false,true})try(Fixture f=new Fixture(dir,"X"+reverse)){
            require(f.root.compile("!anchor(1);",null,false),"actual parent");f.db.connectContext(reverse?"B":"A");f.db.connectContext(reverse?"A":"B");long revision=f.db.getRevision();String before=ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint;Mind child=new Mind(f.root);Rule h=raw(child,"!@x left(x)&&right(x)->p(x);");Member x=new Member(child,ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000));List<Cut> cuts=new ArrayList<>();Member b=null;String aKey=null,bKey=null;Map<String,Donor> ds=new HashMap<>();
            for(ContextConnection connection:f.db.dmzTopology()){Member m=new Member(connection.layer(),ContextProductionInventory.inspect(connection.layer(),connection.getTarget().getContextId(),connection.getTarget().getRevision(),false,Collections.emptyList(),1000));Cut cut=new Cut(null,Collections.singletonList(m));cuts.add(cut);for(Object o:m.actual.getRules()){Rule r=(Rule)o;if(r.getOrigin().equals("!right(1);")){b=m;bKey=cut.key;ds.put("right",Donor.original(ref(m,r)));}if(r.getOrigin().equals("!~p(1);"))ds.put("p",Donor.original(ref(m,r)));if(r.getOrigin().equals("!left(1);"))aKey=cut.key;}}
            require(b!=null&&aKey!=null,"actual physical members located");Map<String,List<Step>> first=empty(x,cuts);first.put(bKey,Collections.singletonList(residual(x,h,"left",ds)));Request req=request(new Round(first),new Round(empty(x,cuts)));String pending=x.inventory.fingerprint;
            try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,1000)){
                Result r=lease.inspectDependentRounds(req);require(r.barriers.get(0).cuts.get(aKey).finalUnitRefutations.isEmpty(),"actual A sees no same-round B output");require(!r.barriers.get(1).cuts.get(aKey).finalUnitRefutations.isEmpty(),"actual second round proves original admission counterexample");require(r.barriers.get(1).cuts.get(aKey).products.get(0).sources.size()==3,"actual transported proof has exact producing Sources");require(f.db.getRevision()==revision&&pending.equals(ContextProductionInventory.inspect(child,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"owning rounds never write child or revision");raw(child,"!changed(1);");reject(()->lease.inspectDependentRounds(req),"whole pending child guard remains currentness authority");
            }finally{f.root.release(child);}require(before.equals(ContextProductionInventory.inspect(f.root,f.db.getContextId(),revision,true,Collections.emptyList(),1000).fingerprint),"parent unchanged after release");
        }
    }
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("dependent-round-").toString());originalAndPrivate();barriersAndOpposition();alternatives();dependencies();owning();System.out.println("CONTEXT_DEPENDENT_ROUND_PASS checks="+checks);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
